import httpx


def make_proxied_client(proxy_url: str, base_url: str) -> httpx.Client:
    """Create an httpx.Client for base_url that sends all requests through the HTTP proxy at proxy_url.

    Requests to both http and https URLs are proxied.
    Timeout is 5 seconds.
    Adds header 'User-Agent: inventory-sync/1.0' to every request.
    """
    proxies = {
        "http://": proxy_url,
        "https://": proxy_url,
    }
    headers = {"User-Agent": "inventory-sync/1.0"}
    return httpx.Client(base_url=base_url, headers=headers, timeout=5.0, proxies=proxies)

